import React, { useState, useEffect } from 'react';

import { Link } from 'react-router-dom';

import { getFeaturedProducts, getProductCategories, createSubscription } from '../services/api';

import QRCode from 'qrcode';

import { isAuthenticated } from '../util/auth';

import ProductCard from '../components/ProductCard';

import Toast from '../components/Toast';

import { useTheme } from '../context/ThemeContext';

import useToast from '../hooks/useToast';



const Home = () => {

  const [featuredProducts, setFeaturedProducts] = useState([]);

  const [categories, setCategories] = useState([]);

  const [loading, setLoading] = useState(true);

  const [currentSlide, setCurrentSlide] = useState(0);

  const [featureSlide, setFeatureSlide] = useState(0);

  const [featuredSlide, setFeaturedSlide] = useState(0);

  const [selectedPlan, setSelectedPlan] = useState(null);

  const [subscriptionModal, setSubscriptionModal] = useState(false);

  const [loadingSubscription, setLoadingSubscription] = useState(false);

  const [qrCodeModal, setQrCodeModal] = useState(false);

  const [qrCodeData, setQrCodeData] = useState(null);

  const [subscriptionId, setSubscriptionId] = useState(null);

  const { isDarkMode } = useTheme();

  const { toasts, removeToast } = useToast();



  const fetchData = async () => {

    try {

      setLoading(true);

      const [featuredRes, categoriesRes] = await Promise.all([

        getFeaturedProducts(),

        getProductCategories()

      ]);

      setFeaturedProducts(featuredRes.data);

      setCategories(categoriesRes.data);

    } catch (error) {

      console.error('Error fetching data:', error);

} finally {

      setLoading(false);

    }

  };



  useEffect(() => {

    fetchData();

    

    // Auto-rotate hero slides

    const heroInterval = setInterval(() => {

      setCurrentSlide((prev) => (prev + 1) % 3);

    }, 4000);

    

    // Auto-rotate feature slides

    const featureInterval = setInterval(() => {

      setFeatureSlide((prev) => (prev + 1) % 3);

    }, 3000);

    

    return () => {

      clearInterval(heroInterval);

      clearInterval(featureInterval);

    };

  }, [fetchData, setCurrentSlide, setFeatureSlide]);



  const handleSubscribe = async (planType) => {

    if (!userAuthenticated) {

      // Redirect to login if not authenticated

      window.location.href = '/login';

      return;

    }

    setSelectedPlan(planType);

    setSubscriptionModal(true);

  };



  const createSubscriptionHandler = async () => {

    if (!selectedPlan) return;

    

    try {

      setLoadingSubscription(true);

      

      const subscriptionData = {

        planType: selectedPlan,

        startDate: new Date().toISOString(),

        status: 'pending_payment'

      };

      

      const response = await createSubscription(subscriptionData);

      

      if (response.status === 201 || response.status === 200) {

        const subscription = response.data;
        
        // Generate payment QR code
        const paymentData = {
          subscriptionId: subscription._id,
          planType: selectedPlan,
          amount: subscription.pricing?.totalAmount || getPlanDetails(selectedPlan)?.price || 0,
          userId: subscription.user,
          timestamp: new Date().toISOString()
        };

        // Generate QR code
        const qrCodeUrl = await QRCode.toDataURL(JSON.stringify(paymentData), {
          width: 256,
          margin: 2,
          color: {
            dark: '#000000',
            light: '#FFFFFF'
          }
        });

        // Send payment notification to admin
        await fetch('/api/admin/payment-notification', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          },
          body: JSON.stringify({
            subscriptionId: subscription._id,
            planType: selectedPlan,
            amount: paymentData.amount,
            userId: subscription.user,
            paymentData: paymentData,
            message: `New subscription payment pending for ${selectedPlan} plan - Amount: ₹${paymentData.amount}`
          })
        });

        // Set QR code data and show modal
        setQrCodeData(qrCodeUrl);
        setSubscriptionId(subscription._id);
        setSubscriptionModal(false);
        setQrCodeModal(true);
        setSelectedPlan(null);

      } else {

        // Error - show error message

        alert(response.data?.message || 'Failed to create subscription');

      }

    } catch (error) {

      console.error('Subscription error:', error);

      alert('An error occurred while creating subscription');

    } finally {

      setLoadingSubscription(false);

    }

  };



  const getPlanDetails = (planType) => {

    const plans = {

      daily: {

        name: 'Daily Plan',

        price: 29,

        duration: 'day',

        features: [

          '500ml Fresh Milk Daily',

          '6:00 AM - 7:00 AM Delivery',

          'Pause Anytime',

          'Free Delivery'

        ]

      },

      weekly: {

        name: 'Weekly Plan',

        price: 189,

        duration: 'week',

        features: [

          '3.5L Milk Per Week',

          'Flexible Delivery Days',

          '10% Discount',

          'Free Delivery'

        ]

      },

      monthly: {

        name: 'Monthly Plan',

        price: 799,

        duration: 'month',

        features: [

          '15L Milk Per Month',

          'Custom Schedule',

          '20% Discount',

          'Free Delivery + Priority'

        ]

      }

    };

    

    return plans[planType] || null;

  };



  const userAuthenticated = isAuthenticated();



  return (

    <div className="fade-in">

      {/* Animated Hero Section */}

      <section className="relative min-h-screen flex items-center justify-center overflow-hidden rounded-2xl mb-12">

        {/* Animated Background */}

